import fs from 'node:fs/promises';
import path from 'node:path';
import crypto from 'node:crypto';
import type { SyncConfig } from './config.js';

const GENERATED_MARKER = '// @generated by @hexagen/sync';

/**
 * Checks if file content was generated by sync (safe to overwrite unless --force=false).
 */
export function isGeneratedFile(content: string): boolean {
  return content.includes(GENERATED_MARKER);
}

/**
 * Checks if path is a protected monorepo root file.
 */
export function isProtectedRoot(filePath: string, config: SyncConfig): boolean {
  const protectedFiles: readonly string[] = config.manifest?.generator?.sync
    ?.protectedRootFiles ?? [
    'package.json',
    'tsconfig.json',
    'tsconfig.base.json',
    '.architecture.yaml',
    'turbo.json',
    'yarn.lock',
    '.gitignore',
    'README.md',
    '.env*',
  ];

  const relative = path.relative(config.workspaceRoot, filePath);
  const isRootLevel =
    !relative.startsWith('packages/') && !relative.startsWith('tools/');

  return (
    isRootLevel &&
    protectedFiles.some((f) => relative.endsWith(f) || relative.includes(f))
  );
}

/**
 * SHA256 hash for content equality check.
 */
function contentHash(content: string): string {
  return crypto.createHash('sha256').update(content).digest('hex');
}

/**
 * Safe, idempotent file writer. Strictly respects dry-run (read-only), force flags,
 * protected root rules, and non-generated file protection.
 *
 * @param skipGeneratedCheck - If true, bypass isGeneratedFile check (for managed files like package.json that can't carry a marker)
 */
export async function safeWriteFile(
  filePath: string,
  content: string,
  config: SyncConfig,
  skipGeneratedCheck: boolean = false
): Promise<'created' | 'updated' | 'unchanged' | 'skipped' | 'protected'> {
  const { dryRun, force, logger, workspaceRoot } = config;
  const relativePath = path.relative(workspaceRoot, filePath);

  let exists = false;
  let currentContent = '';
  let currentHash = '';

  try {
    currentContent = await fs.readFile(filePath, 'utf8');
    currentHash = contentHash(currentContent);
    exists = true;
  } catch (e) {
    if (e instanceof Error && 'code' in e && e.code === 'ENOENT') {
      // File does not exist — proceed
    } else {
      throw e;
    }
  }

  const newHash = contentHash(content);

  // Early exit: content unchanged
  if (exists && currentHash === newHash) {
    logger.debug(`unchanged ${relativePath}`);
    return 'unchanged';
  }

  // Dry-run simulation — no disk mutation
  if (dryRun) {
    const action = exists ? 'update' : 'create';
    logger.info(`[DRY-RUN] would ${action} ${relativePath}`);
    return exists ? 'updated' : 'created';
  }

  // Protection checks
  if (isProtectedRoot(filePath, config) && !force) {
    logger.warn(`skipped (root protected, use --force) ${relativePath}`);
    return 'protected';
  }

  // Non-generated file protection — skipped unless override
  if (
    exists &&
    !force &&
    !skipGeneratedCheck &&
    !isGeneratedFile(currentContent)
  ) {
    logger.warn(
      `skipped (protected non-generated file, use --force) ${relativePath}`
    );
    return 'skipped';
  }

  // Actual mutation
  await fs.mkdir(path.dirname(filePath), { recursive: true });
  await fs.writeFile(filePath, content, 'utf8');

  const status = exists ? 'updated' : 'created';
  logger.info(`${status} ${relativePath}`);
  return status;
}
